import React from 'react';
import { Link } from 'react-router-dom';
import { Card, Container, Row, Col } from 'react-bootstrap';

const Home = () => {
  const cardStyle = {
    width: '18rem',
    margin: '20px',
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    textDecoration: 'none',
    color: '#292940',
    border: 'none',
    borderRadius: '12px',
    overflow: 'hidden',
    boxShadow: '0 4px 15px rgba(0, 0, 0, 0.08)'
  };

  const cardHover = {
    transform: 'translateY(-5px)',
    boxShadow: '0 8px 25px rgba(21, 114, 254, 0.2)'
  };

  return (
    <Container className="py-5" style={{ backgroundColor: '#fbfcfe' }}>
      <h1 className="text-center mb-5" style={{ 
        color: '#292940',
        fontWeight: '700',
        textShadow: '1px 1px 2px rgba(0,0,0,0.1)'
      }}>
        Course Management System
      </h1>
      <Row className="justify-content-center">
        <Col md={3} className="text-center">
          <Link to="/students" style={cardStyle} className="card-link">
            <Card className="h-100" style={cardStyle} 
              onMouseEnter={e => e.currentTarget.style.transform = cardHover.transform}
              onMouseLeave={e => e.currentTarget.style.transform = 'none'}
            >
              <div style={{
                height: '8px',
                background: 'linear-gradient(90deg, #1572fe, #c08cee)'
              }} />
              <Card.Body>
                <Card.Title style={{ color: '#1572fe' }}>Students</Card.Title>
                <Card.Text style={{ color: '#5c6b7b' }}>
                  Manage student records and information.
                </Card.Text>
              </Card.Body>
            </Card>
          </Link>
        </Col>

        <Col md={3} className="text-center">
          <Link to="/courses" style={cardStyle} className="card-link">
            <Card className="h-100" style={cardStyle} 
              onMouseEnter={e => e.currentTarget.style.transform = cardHover.transform}
              onMouseLeave={e => e.currentTarget.style.transform = 'none'}
            >
              <div style={{
                height: '8px',
                background: 'linear-gradient(90deg, #1572fe, #c08cee)'
              }} />
              <Card.Body>
                <Card.Title style={{ color: '#eeac5c' }}>Courses</Card.Title>
                <Card.Text style={{ color: '#5c6b7b' }}>
                  View and manage course offerings.
                </Card.Text>
              </Card.Body>
            </Card>
          </Link>
        </Col>

        <Col md={3} className="text-center">
          <Link to="/registrations" style={cardStyle} className="card-link">
            <Card className="h-100" style={cardStyle} 
              onMouseEnter={e => e.currentTarget.style.transform = cardHover.transform}
              onMouseLeave={e => e.currentTarget.style.transform = 'none'}
            >
              <div style={{
                height: '8px',
                background: 'linear-gradient(90deg, #1572fe, #c08cee)'
              }} />
              <Card.Body>
                <Card.Title style={{ color: '#c08cee' }}>Registrations</Card.Title>
                <Card.Text style={{ color: '#5c6b7b' }}>
                  Handle course registrations and enrollments.
                </Card.Text>
              </Card.Body>
            </Card>
          </Link>
        </Col>

        <Col md={3} className="text-center">
          <Link to="/results" style={cardStyle} className="card-link">
            <Card className="h-100" style={cardStyle} 
              onMouseEnter={e => e.currentTarget.style.transform = cardHover.transform}
              onMouseLeave={e => e.currentTarget.style.transform = 'none'}
            >
              <div style={{
                height: '8px',
                background: 'linear-gradient(90deg, #1572fe, #c08cee)'
              }} />
              <Card.Body>
                <Card.Title style={{ color: '#292940' }}>Results</Card.Title>
                <Card.Text style={{ color: '#5c6b7b' }}>
                  View and manage student results.
                </Card.Text>
              </Card.Body>
            </Card>
          </Link>
        </Col>
      </Row>
    </Container>
  );
};

export default Home;
